import{z as d,x as B,o as l,c as A,q as n,j as s,D as r,d as t,s as i,S as E,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"四叉树与八叉树","description":"","frontmatter":{"title":"四叉树与八叉树","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/quadtree-octree.md","filePath":"cs/quadtree-octree.md","lastUpdated":1791063341000}'),p={name:"cs/quadtree-octree.md"};function m(u,a,c,D,f,h){const o=B("Mermaid");return l(),A("div",null,[a[2]||(a[2]=n('<h1 id="四叉树与八叉树" tabindex="-1">四叉树与八叉树 <a class="header-anchor" href="#四叉树与八叉树" aria-label="Permalink to &quot;四叉树与八叉树&quot;">​</a></h1><div class="epigraph"><p>正方形一分为四、立方体一分为八；空块不再切。分辨率跟物体走，不跟数据页扇出走。</p><footer>—— 据 Finkel and Bentley, Quad Trees: A Data Structure for Retrieval on Composite Keys, Acta Informatica 1974；Samet, Foundations of Multidimensional and Metric Data Structures 整理</footer></div><p><a href="/cs/r-tree">上一课</a> 的 MBR 自适应且可重叠。<a href="/cs/kd-tree">k-d 树</a> 按数据中位数切。若域是固定包围盒、物体是图像像素或体素，用规则分裂更简单。本课不写页分裂启发式。缺口是四叉树 / 八叉树：几何中点切，到容量或深度停止。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>平面区域或点集，反复把方块分成四象限，块内点少于阈值或到达最大深度则成叶。<span class="marginnote">可以把它想象成地图缩放：世界先是一整张图，哪里点密集就把哪一格放大成四格，稀疏处一格到底——分辨率跟着数据密度走，而不是全图平均用力。</span>八叉树对立方体八分，用于三维场景、体素。查询：与询问区相交的块才下钻。缺口是<strong>规则四/八分</strong>，编码可用象限位，邻接查找有经典算法（Samet）。</p><p><span class="marginnote">Finkel and Bentley 1974。点四叉树与区域四叉树（黑白像素合并）是两种合同，本课都点名：前者叶存点，后者叶存均质块。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>插入点：从根走到含该点的叶，溢出则分裂再插。删除可能合并兄弟（若都变稀）。范围查询与 k-d 类似剪不相交方块。最近邻可优先探近的象限。</p>',8)),(l(),s(E,null,{default:r(()=>[i(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SQ%5B%22%E6%AD%A3%E6%96%B9%E5%BD%A2%22%5D%20--%3E%20Q0%5B%22%E8%B1%A1%E9%99%90%2000%22%5D%0A%20%20SQ%20--%3E%20Q1%5B%22%E8%B1%A1%E9%99%90%2001%22%5D%0A%20%20SQ%20--%3E%20Q2%5B%22%E8%B1%A1%E9%99%90%2010%22%5D%0A%20%20SQ%20--%3E%20Q3%5B%22%E8%B1%A1%E9%99%90%2011%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"与 R 树：无 MBR 重叠问题，但空区域仍占树路径，偏斜数据会不平衡。与网格：四叉树是自适应分辨率网格。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[t("深度 \\(O(\\log(1/\\varepsilon))\\) 于最小特征尺寸，不是 \\(O(\\log n)\\)。"),e("span",{class:"marginnote"},"数字实例：要把最小可分辨块边长压到原边长的千分之一，深度约 \\(\\log_2 1000 \\approx 10\\) 层——即使块里塞了一百万个点，深度也由几何精度决定，与点数基本无关。"),t("最坏一条链（点挤在角上反复切）。 "),e("span",{class:"marginnote"},"初学者容易以为四叉树和平衡二叉树一样「深度 \\(O(\\log n)\\)、天然平衡」；实际上深度由最小特征尺寸决定，所有点挤在一个角上时会退化成一条长链——「到容量就切」的规则对偏斜数据毫无防御。"),t("三维八叉同构，只是扇出 8。本课不把 GPU 层次包围盒（BVH）写完，只承认同族。")],-1)),a[6]||(a[6]=e("p",null,"空间填充曲线把四叉块序线性化，便于外存与缓存——下一课专门收 Hilbert / Morton。",-1)),(l(),s(E,null,{default:r(()=>[i(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%8C%83%E5%9B%B4%E6%9F%A5%E8%AF%A2%E7%9F%A9%E5%BD%A2%20R%22%5D%20--%3E%20ROOT%5B%22%E4%BB%8E%E6%A0%B9%E5%9D%97%E5%87%BA%E5%8F%91%22%5D%0A%20%20ROOT%20--%3E%20HIT%7B%22%E5%9D%97%E4%B8%8E%20R%20%E7%9B%B8%E4%BA%A4%EF%BC%9F%22%7D%0A%20%20HIT%20--%3E%7C%E5%90%A6%7C%20SKIP%5B%22%E6%95%B4%E5%9D%97%E5%89%AA%E6%8E%89%22%5D%0A%20%20HIT%20--%3E%7C%E6%98%AF%7C%20LEAF%7B%22%E5%B7%B2%E5%88%B0%E5%8F%B6%E5%9D%97%EF%BC%9F%22%7D%0A%20%20LEAF%20--%3E%7C%E5%90%A6%7C%20SUB%5B%22%E5%9B%9B%E5%88%86%E4%B8%8B%E9%92%BB%E5%AD%90%E5%9D%97%22%5D%0A%20%20SUB%20--%3E%20HIT%0A%20%20LEAF%20--%3E%7C%E6%98%AF%7C%20OUT%5B%22%E6%94%B6%E9%9B%86%E5%8F%B6%E5%86%85%E7%82%B9%E5%85%A5%E7%BB%93%E6%9E%9C%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写压缩四叉树的全部指针消除。高维 \\(2^k\\) 叉爆炸，勿把八叉推广到 20 维。字符串与后缀不是空间树。</p><p>后课默认：规则空间层次用四叉/八叉。要把块序变成一维局部性，用空间填充曲线。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>四叉/八叉：规则中点分裂，叶达容量或深度。</li><li>平衡不保证；偏斜退化。</li><li>下一课用曲线把多维块排成一维。</li><li>出处：Finkel and Bentley, 1974；Samet 的多维结构综述与专著。</li></ul>',5))])}const S=d(p,[["render",m]]);export{_ as __pageData,S as default};
